 */
@Component
@RequiredArgsConstructor
public class FavoriteListingAlertListener {

    private final InterestRepository interestRepository;
    private final NotificationCommandService notificationCommandService;

    @EventListener
    public void onSaleBidRegistered(SaleBidRegisteredEvent event) {
        List<Interest> interests = interestRepository.findAllByProductColorId(event.productColorId());

        for (Interest interest : interests) {
            User user = interest.getUser();
            if (user == null || user.getId().equals(event.sellerId()) || !user.isActive()) {
                continue;
            }

            notificationCommandService.createNotification(
                    user.getId(),
                    NotificationCategory.SHOPPING,
                    NotificationType.FAVORITE,
                    String.format("관심 상품 [%s] 사이즈 %s에 새 판매 입찰이 등록되었습니다. 판매 희망가 %d원",
                            event.productName(), event.size(), event.bidPrice())
            );
        }
    }
}

